  let t = clamp(dot(p - a, ab) / abLenSq, 0.0, 1.0);
  let offset = p - (a + ab * t);
  let tangent = ab * inverseSqrt(abLenSq);
  let leftNormal = vec2f(-tangent.y, tangent.x);
  return vec4f(length(offset), t, leftNormal);
